.trig, .trig-panel, .trig-menu{
  --trig-ink:#141019;
  --trig-raised:#241D31; --trig-raised-2:#2E2540;
  --trig-line:rgba(255,255,255,.09); --trig-line-2:rgba(255,255,255,.16);
  --trig-text:#ECE7F2; --trig-dim:#9990A6; --trig-faint:#6E667C;
  --trig-signal:#3BE0C4;
  --trig-admin:#8B8397; --trig-sm:#5B9CFF; --trig-rcp:#F2A63C; --trig-out:#3BE0C4;
  --trig-mono:ui-monospace,"SF Mono","JetBrains Mono",Menlo,Consolas,monospace;
  --trig-ui:ui-sans-serif,system-ui,-apple-system,"Segoe UI",sans-serif;
}
.trig{position:fixed;right:20px;bottom:88px;z-index:40;font-family:var(--trig-ui)}
/* Below lg the global tab bar owns the bottom edge (SR-5312). */
@media (max-width:1023px){.trig:not(.trig-side){bottom:calc(var(--app-tabbar-h) + 16px)}}
/* Right-edge dock (SR-5312 rider): slim mid-right tab, clear of the tab bar
   entirely; panel expands inward via the popover's side="left". */
.trig.trig-side{right:0;bottom:auto;top:50%;transform:translateY(-50%);padding-right:env(safe-area-inset-right)}
.trig-vtab{display:flex;flex-direction:column;align-items:center;gap:8px;cursor:pointer;
  width:32px;padding:12px 4px;border-radius:10px 0 0 10px;
  background:linear-gradient(180deg,#1c1626,#140f1d);border:1px solid var(--trig-line-2);border-right:0;
  color:var(--trig-text);box-shadow:0 10px 30px -12px rgba(0,0,0,.7);transition:border-color .15s}
.trig-vtab:hover{border-color:color-mix(in srgb,var(--trig-signal) 45%,var(--trig-line-2))}
.trig-vtab:focus-visible{outline:2px solid var(--trig-signal);outline-offset:2px}
.trig-vtab .trig-ctx{writing-mode:vertical-rl}
.trig-vtab .trig-caret{transform:rotate(-90deg)}
.trig-anchor{position:absolute;right:0;bottom:0;width:0;height:0;pointer-events:none}
.trig-hidden{visibility:hidden}
.trig-pill{display:inline-flex;align-items:center;gap:9px;cursor:pointer;
  background:linear-gradient(180deg,#1c1626,#140f1d);border:1px solid var(--trig-line-2);
  border-radius:999px;padding:8px 12px 8px 10px;color:var(--trig-text);
  box-shadow:0 10px 30px -12px rgba(0,0,0,.7);transition:border-color .15s,transform .15s}
.trig-pill:hover{border-color:color-mix(in srgb,var(--trig-signal) 45%,var(--trig-line-2));transform:translateY(-1px)}
.trig-pill:focus-visible{outline:2px solid var(--trig-signal);outline-offset:2px}
.trig-wrench{width:24px;height:24px;border-radius:7px;display:grid;place-items:center;
  background:var(--trig-ink);border:1px solid var(--trig-line);color:var(--trig-signal)}
.trig-ctx{display:inline-flex;align-items:center;gap:7px;font-family:var(--trig-mono);font-size:12px}
.trig-rdot{width:8px;height:8px;border-radius:2px}
.trig-code{color:var(--trig-dim)} .trig-code b{color:var(--trig-text)}
.trig-caret{color:var(--trig-faint)}
.trig-panel{font-family:var(--trig-ui);width:340px !important;background:linear-gradient(180deg,#191322,#120e19);
  border:1px solid var(--trig-line-2);border-radius:15px;overflow:hidden;
  box-shadow:0 26px 60px -20px rgba(0,0,0,.75)}
.trig-rail{height:4px;background:repeating-linear-gradient(-45deg,var(--trig-signal) 0 9px,#10322c 9px 18px);opacity:.9}
.trig-head{display:flex;align-items:center;gap:9px;padding:12px 14px 10px}
.trig-live{width:7px;height:7px;border-radius:50%;background:var(--trig-signal);box-shadow:0 0 8px var(--trig-signal)}
@media (prefers-reduced-motion:no-preference){.trig-live{animation:trig-pulse 2s ease-in-out infinite}}
@keyframes trig-pulse{50%{opacity:.35}}
.trig-title{font-size:10.5px;letter-spacing:.2em;font-weight:800;color:var(--trig-text)}
.trig-admintag{margin-left:auto;font-size:8.5px;letter-spacing:.12em;text-transform:uppercase;font-weight:700;
  color:var(--trig-admin);border:1px solid var(--trig-line);border-radius:6px;padding:3px 6px}
.trig-x{flex:0 0 auto;height:24px !important;width:24px !important;border:1px solid var(--trig-line);border-radius:7px;
  color:var(--trig-faint);background:transparent}
.trig-x:hover{color:var(--trig-text);background:transparent}
.trig-sect{padding:11px 14px;border-top:1px solid var(--trig-line)}
.trig-cap{display:block;font-size:8.5px;letter-spacing:.18em;text-transform:uppercase;color:var(--trig-faint);font-weight:700;margin-bottom:8px}
.trig-readout{display:flex;align-items:center;flex-wrap:nowrap;gap:8px;overflow:hidden;font-family:var(--trig-mono);font-size:11.5px}
.trig-rolechip{display:inline-flex;align-items:center;gap:6px;font-weight:700;flex:0 0 auto}
.trig-dot{width:9px;height:9px;border-radius:3px;flex:0 0 auto}
.trig-divider{width:1px;height:12px;background:var(--trig-line-2);flex:0 0 auto}
.trig-field{display:inline-flex;align-items:center;gap:6px;color:var(--trig-text);flex:0 0 auto;white-space:nowrap}
.trig-field b{color:var(--trig-text);font-weight:700}
.trig-field-store{flex:0 1 auto;min-width:0}
.trig-field-store>span:last-child,.trig-field-store{overflow:hidden;text-overflow:ellipsis}
.trig-fieldlabel{font-size:8.5px;letter-spacing:.1em;text-transform:uppercase;color:var(--trig-faint);font-weight:700;flex:0 0 auto}
.trig-store{color:var(--trig-dim)}
.trig-roles{display:grid;grid-template-columns:1fr 1fr;gap:6px}
.trig-role{justify-content:flex-start !important;height:auto !important;min-height:0;cursor:pointer;text-align:left;
  border:1px solid var(--trig-line-2);background:var(--trig-raised);color:var(--trig-dim);border-radius:9px;
  padding:9px 10px;display:flex;align-items:center;gap:8px;font-family:var(--trig-ui);font-weight:700;font-size:12px;
  transition:border-color .12s,background .12s,color .12s}
.trig-role .trig-dot{background:var(--rc)}
.trig-role:hover{color:var(--trig-text);background:var(--trig-raised)}
.trig-role:focus-visible{outline:2px solid var(--trig-signal);outline-offset:2px}
.trig-role[data-state="on"],.trig-role[aria-pressed="true"]{color:#0c0a12;background:var(--rc);border-color:var(--rc)}
.trig-role[data-state="on"] .trig-dot,.trig-role[aria-pressed="true"] .trig-dot{background:rgba(12,10,18,.5)}
.trig-role:disabled{opacity:.5;cursor:not-allowed}
.trig-row{display:flex;gap:8px;align-items:center}
.trig-select-trigger{width:auto !important;flex:0 0 auto;gap:10px;height:36px !important;border:1px solid var(--trig-line-2);background:var(--trig-raised);
  color:var(--trig-text);border-radius:9px;padding:0 12px;font-family:var(--trig-ui);font-weight:650;font-size:12px;box-shadow:none}
.trig-select-trigger:hover{background:var(--trig-raised-2)}
.trig-select-inner{display:inline-flex;align-items:center;gap:9px}
.trig-select-div{width:1px;height:12px;background:var(--trig-line-2);flex:0 0 auto}
.trig-select-label{font-size:8.5px;letter-spacing:.14em;text-transform:uppercase;color:var(--trig-faint);font-weight:700}
.trig-select-val{font-family:var(--trig-mono);font-size:12px;color:var(--trig-text)}
.trig-menu{background:var(--trig-raised);border:1px solid var(--trig-line-2);color:var(--trig-text)}
.trig-menu-item{color:var(--trig-text)}
.trig-btn{cursor:pointer;border:1px solid var(--trig-line-2);background:var(--trig-raised);color:var(--trig-text);
  border-radius:9px;height:auto !important;padding:9px 12px;font-family:var(--trig-ui);font-weight:650;font-size:12px;
  display:inline-flex;align-items:center;justify-content:center;gap:7px}
.trig-btn.trig-wide{flex:1}
.trig-btn.trig-go{background:var(--rc,var(--trig-signal));border-color:var(--rc,var(--trig-signal));color:#08211c;font-weight:800}
.trig-btn.trig-go:hover{background:var(--rc,var(--trig-signal));filter:brightness(1.06)}
.trig-btn:disabled{opacity:.4;cursor:not-allowed}
.trig-nav{display:flex;gap:6px}
.trig-navlink{flex:1;height:auto !important;min-height:0;padding:8px 6px !important;font-size:10px;letter-spacing:.08em;
  text-transform:uppercase;font-weight:700;color:var(--trig-faint);border-radius:8px;border:1px solid transparent;background:transparent}
.trig-navlink:hover{color:var(--trig-text);background:transparent}
.trig-navlink[data-here="1"]{color:var(--trig-text);background:var(--trig-raised);border-color:var(--trig-line)}
.trig-neutral{display:flex;gap:8px;align-items:flex-start;border-top:1px solid var(--trig-line);
  background:color-mix(in srgb,var(--trig-admin) 12%,transparent);padding:10px 14px;font-size:11.5px;color:var(--trig-admin)}
.trig-neutral b{color:var(--trig-text)}
.trig-w{flex:0 0 auto;width:15px;height:15px;border-radius:4px;background:var(--trig-admin);color:#12101a;
  display:grid;place-items:center;font-weight:900;font-size:10px;margin-top:1px}
@media (prefers-reduced-motion:reduce){.trig-pill,.trig-role,.trig-btn,.trig-select-trigger{transition:none}}
